set role to inventario_owner;
set search_path = "inventario", public;

begin;

drop policy "bp select" on "responsables";
CREATE POLICY "bp select" ON "responsables" AS RESTRICTIVE FOR select TO inventario_admin USING ( (get_app_user('mode') = 'login' OR ((SELECT coalesce(puede_ver_todo, false) FROM roles WHERE rol = get_app_user('rol')) OR ((SELECT coalesce(puede_ver_propio, false) FROM roles WHERE rol = get_app_user('rol')) AND (responsable = nullif(get_app_user('responsable'), ''))) OR ((SELECT coalesce(puede_ver_dependientes, false) FROM roles WHERE rol = get_app_user('rol')) AND (sector IN (SELECT s.sector FROM sectores s WHERE sector_pertenece(s.sector, nullif(get_app_user('sector'), ''))))))) );
drop policy "bp insert" on "responsables";
CREATE POLICY "bp insert" ON "responsables" AS RESTRICTIVE FOR insert TO inventario_admin WITH CHECK ( ((SELECT coalesce(puede_guardar, false) FROM roles WHERE rol = get_app_user('rol'))) AND (get_app_user('mode') = 'login' OR ((SELECT coalesce(puede_ver_todo, false) FROM roles WHERE rol = get_app_user('rol')) OR ((SELECT coalesce(puede_ver_propio, false) FROM roles WHERE rol = get_app_user('rol')) AND (responsable = nullif(get_app_user('responsable'), ''))) OR ((SELECT coalesce(puede_ver_dependientes, false) FROM roles WHERE rol = get_app_user('rol')) AND (sector IN (SELECT s.sector FROM sectores s WHERE sector_pertenece(s.sector, nullif(get_app_user('sector'), ''))))))) );
drop policy "bp update" on "responsables";
CREATE POLICY "bp update" ON "responsables" AS RESTRICTIVE FOR update TO inventario_admin USING ( ((SELECT coalesce(puede_guardar, false) FROM roles WHERE rol = get_app_user('rol'))) AND (get_app_user('mode') = 'login' OR ((SELECT coalesce(puede_ver_todo, false) FROM roles WHERE rol = get_app_user('rol')) OR ((SELECT coalesce(puede_ver_propio, false) FROM roles WHERE rol = get_app_user('rol')) AND (responsable = nullif(get_app_user('responsable'), ''))) OR ((SELECT coalesce(puede_ver_dependientes, false) FROM roles WHERE rol = get_app_user('rol')) AND (sector IN (SELECT s.sector FROM sectores s WHERE sector_pertenece(s.sector, nullif(get_app_user('sector'), ''))))))) ) WITH CHECK ( ((SELECT coalesce(puede_guardar, false) FROM roles WHERE rol = get_app_user('rol'))) AND (get_app_user('mode') = 'login' OR ((SELECT coalesce(puede_ver_todo, false) FROM roles WHERE rol = get_app_user('rol')) OR ((SELECT coalesce(puede_ver_propio, false) FROM roles WHERE rol = get_app_user('rol')) AND (responsable = nullif(get_app_user('responsable'), ''))) OR ((SELECT coalesce(puede_ver_dependientes, false) FROM roles WHERE rol = get_app_user('rol')) AND (sector IN (SELECT s.sector FROM sectores s WHERE sector_pertenece(s.sector, nullif(get_app_user('sector'), ''))))))) );
drop policy "bp delete" on "responsables";
CREATE POLICY "bp delete" ON "responsables" AS RESTRICTIVE FOR delete TO inventario_admin USING ( ((SELECT coalesce(puede_eliminar, false) FROM roles WHERE rol = get_app_user('rol'))) AND (get_app_user('mode') = 'login' OR ((SELECT coalesce(puede_ver_todo, false) FROM roles WHERE rol = get_app_user('rol')) OR ((SELECT coalesce(puede_ver_propio, false) FROM roles WHERE rol = get_app_user('rol')) AND (responsable = nullif(get_app_user('responsable'), ''))) OR ((SELECT coalesce(puede_ver_dependientes, false) FROM roles WHERE rol = get_app_user('rol')) AND (sector IN (SELECT s.sector FROM sectores s WHERE sector_pertenece(s.sector, nullif(get_app_user('sector'), ''))))))) );

commit;
